class Solution {
  public int maxStudents(char[][] seats) {
    int m = seats.length, n = seats[0].length, full = 1 << n;
    int[] dp = new int[full], nd = new int[full];
    java.util.Arrays.fill(dp, -1);
    dp[0] = 0;
    for (int i = 0; i < m; i++) {
      int avail = 0;
      for (int j = 0; j < n; j++) if (seats[i][j] == '.') avail |= 1 << j;
      java.util.Arrays.fill(nd, -1);
      for (int cur = avail; ; cur = (cur - 1) & avail) {
        if ((cur & (cur << 1)) == 0) {
          int best = -1;
          for (int prev = 0; prev < full; prev++) {
            if (dp[prev] >= 0
                && (cur & (prev << 1)) == 0
                && (cur & (prev >> 1)) == 0
                && dp[prev] > best) best = dp[prev];
          }
          if (best >= 0) nd[cur] = best + Integer.bitCount(cur);
        }
        if (cur == 0) break;
      }
      int[] t = dp;
      dp = nd;
      nd = t;
    }
    int ans = 0;
    for (int v : dp) ans = Math.max(ans, v);
    return ans;
  }
}
